do $$
declare u uuid:=gen_random_uuid();other_user uuid:=gen_random_uuid();p uuid:=gen_random_uuid();s uuid:=gen_random_uuid();oid uuid:=gen_random_uuid();oid2 uuid:=gen_random_uuid();ticket jsonb;again jsonb;quote jsonb;payload jsonb;blocked boolean;before_balance integer;
begin
 insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data,is_anonymous) values(u,u::text||'@example.invalid','{}','{}',false),(other_user,other_user::text||'@example.invalid','{}','{}',false);
 insert into public.dlp_stamp_conversion(user_id,old_points,stamps,discarded) values(u,40999,40,999),(other_user,0,0,0);
 perform set_config('request.jwt.claim.sub',u::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 if public.v80_balance(u)<>40 then raise exception 'Saldo inicial incorrecto';end if;
 ticket:=public.dlp_issue_stamp_code('burger_simple');again:=public.dlp_issue_stamp_code('burger_simple');
 if ticket<>again or public.v80_balance(u)<>40 then raise exception 'Emisión no idempotente o cobro anticipado';end if;
 blocked:=false;begin perform public.dlp_issue_stamp_code('delivery_free',other_user);exception when others then blocked:=true;end;if not blocked then raise exception 'Permite actuar sobre otra cuenta';end if;
 insert into public.products(id,name,price,category_id) select p,'Prueba Simple',100,id from public.categories where name='Burgers' limit 1;
 insert into public.products(id,name,price,category_id) select s,'Prueba starter',50,id from public.categories where name='STARTERS' limit 1;
 payload:=jsonb_build_object('stamp_reward','burger_simple','stamp_product_id',p,'items',jsonb_build_array(jsonb_build_object('productId',p,'quantity',3)),'payment_method','cash','fulfillment_type','pickup');
 quote:=public.v80_stamp_quote(payload);
 if (quote->>'stamps')::int<>20 or (quote->>'discount')::numeric<>100 or quote->>'code'<>ticket->>'code' then raise exception 'Cotización incorrecta';end if;
 insert into public.orders(id,user_id,fulfillment_type,subtotal,total,order_number) values(oid,u,'pickup',300,300,-900000001);
 insert into public.order_items(order_id,product_id,product_name,quantity,price,subtotal) values(oid,p,'Prueba Simple',3,100,300);
 perform public.v80_apply_stamp(oid,quote||jsonb_build_object('product_id',p));
 perform public.v80_apply_stamp(oid,quote||jsonb_build_object('product_id',p));
 if public.v80_balance(u)<>20 or (select total from public.orders where id=oid)<>200 or (select v87_earn_points from public.orders where id=oid)<>2 then raise exception 'Canje, total o sellos ganados incorrectos';end if;
 if (select order_id from public.dlp_stamp_codes where code=(ticket->>'code')::uuid)<>oid then raise exception 'Código no consumido';end if;
 insert into public.orders(id,user_id,fulfillment_type,subtotal,total,order_number) values(oid2,u,'pickup',300,300,-900000002);
 blocked:=false;begin perform public.v80_apply_stamp(oid2,quote);exception when others then blocked:=true;end;if not blocked then raise exception 'Reutilización de código';end if;
 update public.orders set status='completed' where id=oid;
 if public.v80_balance(u)<>22 then raise exception 'No acredita por unidad pagada';end if;
 update public.orders set status='cancelled' where id=oid;
 if public.v80_balance(u)<>40 then raise exception 'Cancelación no revierte sellos';end if;
 update public.orders set status='cancelled' where id=oid;
 if public.v80_balance(u)<>40 then raise exception 'Devolución duplicada';end if;
 ticket:=public.dlp_issue_stamp_code('starter_free');
 quote:=public.v80_stamp_quote(jsonb_build_object('stamp_reward','starter_free','stamp_product_id',s,'items',jsonb_build_array(jsonb_build_object('productId',s,'quantity',1)),'payment_method','cash','fulfillment_type','pickup'));
 if (quote->>'stamps')::int<>10 or (quote->>'discount')::numeric<>50 then raise exception 'Starter inválido';end if;
 ticket:=public.dlp_issue_stamp_code('delivery_free');
 blocked:=false;begin perform public.v80_stamp_quote(jsonb_build_object('stamp_reward','delivery_free','items',jsonb_build_array(jsonb_build_object('productId',p,'quantity',2)),'payment_method','cash','fulfillment_type','delivery'));exception when others then if sqlerrm not like '%3 hamburguesas%' then raise;end if;blocked:=true;end;if not blocked then raise exception 'Delivery con solo dos hamburguesas';end if;
 insert into public.delivery_zones(name,fee,polygon) values('Prueba transaccional sellos',30,'[{"lat":-88,"lng":1},{"lat":-88,"lng":3},{"lat":-86,"lng":3},{"lat":-86,"lng":1}]');
 quote:=public.v80_stamp_quote(jsonb_build_object('stamp_reward','delivery_free','items',jsonb_build_array(jsonb_build_object('productId',p,'quantity',3)),'payment_method','cash','fulfillment_type','delivery','lat',-87,'lng',2));
 if (quote->>'stamps')::int<>5 or (quote->>'delivery_discount')::numeric<>30 then raise exception 'Delivery con tres hamburguesas incorrecto';end if;
 perform set_config('request.jwt.claim.sub',other_user::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',other_user,'role','authenticated')::text,true);
 blocked:=false;begin perform public.dlp_issue_stamp_code('delivery_free');exception when others then blocked:=true;end;if not blocked then raise exception 'Canje sin saldo';end if;
 if has_table_privilege('authenticated','public.dlp_stamp_codes','select') or has_table_privilege('anon','public.dlp_stamp_movements','insert') or has_function_privilege('anon','public.dlp_issue_stamp_code(text,uuid)','execute') or has_function_privilege('authenticated','public.v80_apply_stamp(uuid,jsonb)','execute') then raise exception 'Permisos incorrectos';end if;
end $$;
